import type { PluginOptions } from "./types.js";

const execFileAsync = promisify(execFile);

const NPM_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes
const INIT_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes

/**
 * Install the codegraph extension into the target.
 *
 * The extension ships with a `node_modules/` directory that should NOT be
 * shipped to consumers (size, platform mismatch, npm registry churn). Instead
 * we copy the source files + package.json + .gitignore and then run
 * `npm install` against the package.json to materialise dependencies.
 */
export async function installCodegraph(target: string, opts: PluginOptions): Promise<void> {
  const logger = opts.logger;
  const source = resolveAsset(".pi/extensions/codegraph");
  const destination = join(target, ".pi", "extensions", "codegraph");

  if (!existsSync(source)) {
    logger.warn(`Missing codegraph asset directory: ${source}`);
    return;
  }

  // Copy everything except node_modules / package-lock.json (lock is rebuilt by npm install).
  if (opts.dryRun) {
    copyDir(source, destination, {
      dryRun: true,
      filter: (_abs, rel) => rel !== "node_modules" && rel !== "package-lock.json",
    });
    logger.info(`[dry-run] npm install (skipped)`);
    logger.info(`[dry-run] codegraph init (skipped)`);
    return;
  }

  copyDir(source, destination, {
    filter: (_abs, rel) => rel !== "node_modules" && rel !== "package-lock.json",
  });
  logger.info(`copied extensions/codegraph`);

  // Ensure .gitignore pins node_modules.
  const gitignore = join(destination, ".gitignore");
  if (!existsSync(gitignore)) {
    atomicWriteFile(gitignore, "node_modules\n");
  }

  // Run npm install in the destination.
  try {
    logger.info(`running npm install (timeout ${NPM_TIMEOUT_MS / 1000}s)`);
    await execFileAsync("npm", ["install", "--no-audit", "--no-fund", "--loglevel=warn"], {
      cwd: destination,
      timeout: NPM_TIMEOUT_MS,
      maxBuffer: 4 * 1024 * 1024,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`codegraph npm install failed: ${message}`);
  }

  // codegraph init is best-effort: the user can run it manually later.
  if (!existsSync(join(target, ".codegraph"))) {
    try {
      logger.info(`running codegraph init (timeout ${INIT_TIMEOUT_MS / 1000}s)`);
      await execFileAsync("codegraph", ["init"], {
        cwd: target,
        timeout: INIT_TIMEOUT_MS,
        maxBuffer: 4 * 1024 * 1024,
      });
    } catch (error) {
      logger.warn(`codegraph init failed (non-fatal): ${error instanceof Error ? error.message : String(error)}`);
      logger.warn(`run \`codegraph init\` inside ${target} manually before using codegraph tools`);
    }
  } else {
    logger.info(`.codegraph already present, skipping init`);
  }
}

import { copyFileSync, mkdirSync, readdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";

export interface CopyOptions {
  filter?: (source: string, relativePath: string) => boolean;
  dryRun?: boolean;
}

/** Recursively copy a directory, optionally filtering entries or running as a preview. */
export function copyDir(src: string, dest: string, options: CopyOptions = {}): void {
  const copy = (sourceDir: string, destinationDir: string, relativeDir: string): void => {
    for (const entry of readdirSync(sourceDir)) {
      const source = join(sourceDir, entry);
      const entryRelativePath = relativeDir ? join(relativeDir, entry) : entry;
      if (options.filter && !options.filter(source, entryRelativePath)) continue;

      const destination = join(destinationDir, entry);
      if (statSync(source).isDirectory()) {
        if (!options.dryRun) mkdirSync(destination, { recursive: true });
        copy(source, destination, entryRelativePath);
      } else {
        if (options.dryRun) {
          console.log(`copy ${entryRelativePath}`);
        } else {
          mkdirSync(dirname(destination), { recursive: true });
          copyFileSync(source, destination);
        }
      }
    }
  };

  copy(src, dest, "");
}

import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, resolve } from "node:path";
import { homedir } from "node:os";

/** Locate the package root from either dist/ or the TypeScript source tree. */
export function resolvePackageRoot(): string {
  let current = dirname(fileURLToPath(import.meta.url));

  while (true) {
    if (existsSync(join(current, "package.json"))) return current;
    const parent = dirname(current);
    if (parent === current) break;
    current = parent;
  }

  throw new Error(`Unable to locate pisquad package root from ${import.meta.url}`);
}

/** Resolve a path relative to the assets embedded in this package. */
export function resolveAsset(rel: string): string {
  return join(resolvePackageRoot(), "assets", rel);
}

/** Resolve an install target, expanding the conventional ~/ prefix. */
export function resolveTarget(input?: string, cwd = process.cwd()): string {
  const value = input ?? cwd;
  const expanded = value === "~" ? homedir() : value.startsWith("~/") ? join(homedir(), value.slice(2)) : value;
  return resolve(cwd, expanded);
}

/** Return the state file belonging to an install target. */
export function stateFile(target: string): string {
  return join(target, ".pi", ".pisquad", "state.json");
}

import { logger } from "../lib/logger.js";

/**
 * Default command handler.
 *
 * Commander's "no subcommand" hook is wired here so that running `pisquad`
 * with no arguments behaves like `pisquad install`.
 */
export async function defaultCommand(): Promise<void> {
  logger.step("default command → install");
  const { installCommand } = await import("./install.js");
  await installCommand({});
}

import { existsSync, mkdirSync, readdirSync, renameSync, rmdirSync, unlinkSync, writeFileSync } from "node:fs";
import { dirname, join, basename } from "node:path";
import { randomBytes } from "node:crypto";

export function ensureDir(path: string): void {
  mkdirSync(path, { recursive: true });
}

export function pathExists(path: string): boolean {
  return existsSync(path);
}

/** Write a file through a same-directory temporary file and atomic rename. */
export function atomicWriteFile(path: string, content: string): void {
  ensureDir(dirname(path));
  const temporary = join(dirname(path), `.${basename(path)}.${process.pid}.${randomBytes(6).toString("hex")}.tmp`);
  try {
    writeFileSync(temporary, content, "utf8");
    renameSync(temporary, path);
  } catch (error) {
    try {
      unlinkSync(temporary);
    } catch {
      // Preserve the original write/rename failure.
    }
    throw error;
  }
}

/** Remove a directory only when it exists and is empty. */
export function removeIfEmpty(path: string): boolean {
  if (!existsSync(path)) return false;
  if (readdirSync(path).length !== 0) return false;
  try {
    rmdirSync(path);
    return true;
  } catch {
    return false;
  }
}

import type { Channels } from "../ui.js";
import { logger as defaultLogger } from "../logger.js";
import type { Logger } from "./types.js";
import { installCore } from "./core.js";
import { installCodegraph } from "./codegraph.js";
import { installEntire } from "./entire.js";

export type { PluginOptions } from "./types.js";

export interface InstallChannelsOptions {
  dryRun?: boolean;
  logger?: Logger;
}

/**
 * Run the channel installation in the documented order: core first (always),
 * then the optional channels the caller requested.
 *
 * Throws when any required step fails. Optional steps (codegraph init, entire
 * enable) already log warnings internally rather than throwing.
 */
export async function installChannels(target: string, channels: Channels, options: InstallChannelsOptions = {}): Promise<void> {
  const logger = options.logger ?? defaultLogger;

  await installCore(target, { dryRun: options.dryRun, logger });

  if (channels.codegraph) {
    await installCodegraph(target, { dryRun: options.dryRun, logger });
  }

  if (channels.entire) {
    await installEntire(target, { dryRun: options.dryRun, logger });
  }
}

export { installCore, installCodegraph, installEntire };

import { copyDir } from "../copy.js";
import { resolveAsset } from "../paths.js";
import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { promisify } from "node:util";
import type { PluginOptions } from "./types.js";

const execFileAsync = promisify(execFile);

const ENABLE_TIMEOUT_MS = 30 * 1000; // 30s — entire enable should be fast

/**
 * Install the entire extension into the target.
 *
 * This plugin fixes the long-standing bash installer bug where selecting the
 * "entire" channel only ran `entire enable --agent pi` without first copying
 * the extension source directory, leaving consumers with a half-installed
 * extension. Both steps now happen here, in this order:
 *
 *   1. Copy assets/.pi/extensions/entire → <target>/.pi/extensions/entire
 *   2. Run `entire enable --agent pi` (idempotent, best-effort)
 */
export async function installEntire(target: string, opts: PluginOptions): Promise<void> {
  const logger = opts.logger;
  const source = resolveAsset(".pi/extensions/entire");
  const destination = join(target, ".pi", "extensions", "entire");

  if (!existsSync(source)) {
    logger.warn(`Missing entire asset directory: ${source}`);
    return;
  }

  if (opts.dryRun) {
    copyDir(source, destination, { dryRun: true });
    logger.info(`[dry-run] entire enable --agent pi (skipped)`);
    return;
  }

  // Step 1: copy the extension directory (the bug fix).
  copyDir(source, destination);
  logger.info(`copied extensions/entire → ${destination}`);

  // Step 2: register with entire (best-effort — entire may not be installed yet).
  try {
    logger.info(`running entire enable --agent pi`);
    await execFileAsync("entire", ["enable", "--agent", "pi"], {
      cwd: target,
      timeout: ENABLE_TIMEOUT_MS,
      maxBuffer: 4 * 1024 * 1024,
    });
  } catch (error) {
    logger.warn(`entire enable --agent pi failed (non-fatal): ${error instanceof Error ? error.message : String(error)}`);
    logger.warn(`re-run \`entire enable --agent pi\` inside ${target} once Entire CLI is installed`);
  }
}

import type { logger as LoggerModule } from "../logger.js";

export type Logger = typeof LoggerModule;

export interface PluginOptions {
  /** When true, plugins should report intended actions without performing them. */
  dryRun?: boolean;
  logger: Logger;
}

export type ChannelName = "core" | "codegraph" | "entire";

import pc from "picocolors";

let verbose = false;

export const logger = {
  setVerbose(value: boolean): void {
    verbose = value;
  },
  info(message: string): void {
    console.log(pc.cyan(message));
  },
  warn(message: string): void {
    console.warn(pc.yellow(message));
  },
  error(message: string): void {
    console.error(pc.red(message));
  },
  success(message: string): void {
    console.log(pc.green(message));
  },
  step(message: string): void {
    if (verbose) console.log(pc.dim(message));
  },
};

export const setVerbose = (value: boolean): void => logger.setVerbose(value);
export const info = (message: string): void => logger.info(message);
export const warn = (message: string): void => logger.warn(message);
export const error = (message: string): void => logger.error(message);
export const success = (message: string): void => logger.success(message);
export const step = (message: string): void => logger.step(message);

import { execFileSync, spawn } from "node:child_process";

export interface ExecCaptureResult {
  stdout: string;
  stderr: string;
  exitCode: number;
}

/** Return true only when both terminal streams are available and tty use is allowed. */
export function isInteractive(): boolean {
  return (
    process.stdin.isTTY === true &&
    process.stdout.isTTY === true &&
    !process.env.CI &&
    !process.env.PISQUAD_NO_TTY
  );
}

/** Find an executable using the host platform's command lookup utility. */
export function which(cmd: string): string | null {
  if (!cmd) return null;

  try {
    const lookup = process.platform === "win32" ? "where.exe" : "sh";
    const args = process.platform === "win32" ? [cmd] : ["-c", 'command -v "$1"', "pisquad-which", cmd];
    const output = execFileSync(lookup, args, {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
    const result = output.trim().split(/\r?\n/)[0];
    return result || null;
  } catch {
    return null;
  }
}

/** Execute a child process without a shell and capture all of its output. */
export function execCapture(cmd: string, args: string[] = []): Promise<ExecCaptureResult> {
  return new Promise((resolve) => {
    let stdout = "";
    let stderr = "";
    let settled = false;

    const finish = (exitCode: number): void => {
      if (settled) return;
      settled = true;
      resolve({ stdout, stderr, exitCode });
    };

    let child;
    try {
      child = spawn(cmd, args, { stdio: ["ignore", "pipe", "pipe"] });
    } catch (error) {
      stderr += error instanceof Error ? error.message : String(error);
      finish(1);
      return;
    }

    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk: string) => {
      stdout += chunk;
    });
    child.stderr.on("data", (chunk: string) => {
      stderr += chunk;
    });
    child.on("error", (error) => {
      stderr += error.message;
      finish(1);
    });
    child.on("close", (code) => {
      finish(code ?? 1);
    });
  });
}

import { Command } from "commander";
import { readCliVersion } from "./lib/version.js";
import { installCommand } from "./commands/install.js";
import { versionCommand } from "./commands/version.js";
import { helpCommand } from "./commands/help.js";

export const program = new Command();

program
  .name("pisquad")
  .description("Install and upgrade the pi-squad development foundation")
  .version(readCliVersion(), "-V, --version", "Print version and exit");

program
  .command("install [path]")
  .description("Install pi-squad into the target directory (default: cwd)")
  .option("-y, --yes", "Skip prompts, install core only")
  .option("--with <channels>", "Comma-separated list of optional channels to install")
  .option("--without <channels>", "Comma-separated list of optional channels to skip")
  .option("--all", "Install every optional channel")
  .option("--dry-run", "Preview changes without writing anything")
  .action(async (pathArg: string | undefined, options: Record<string, unknown>) => {
    await installCommand({
      target: pathArg,
      yes: Boolean(options.yes),
      with: typeof options.with === "string" ? options.with : undefined,
      without: typeof options.without === "string" ? options.without : undefined,
      all: Boolean(options.all),
      dryRun: Boolean(options.dryRun),
    });
  });

program
  .command("version")
  .description("Print CLI and assets versions")
  .action(() => {
    versionCommand();
  });

program
  .command("help [command]")
  .description("Show help for pisquad or one of its subcommands")
  .action((commandName?: string) => {
    helpCommand(commandName);
  });

// No-argument invocation forwards to install.
program.action(async () => {
  const { defaultCommand } = await import("./commands/default.js");
  await defaultCommand();
});

export async function run(argv: string[]): Promise<void> {
  await program.parseAsync(argv);
}

import { checkbox } from "@inquirer/prompts";
import { isInteractive } from "./env.js";

export type OptionalChannel = "codegraph" | "entire";

export interface Channels {
  core: true;
  codegraph: boolean;
  entire: boolean;
}

export interface ChannelDecisionOptions {
  all?: boolean;
  with?: string | string[];
  without?: string | string[];
  yes?: boolean;
  env?: NodeJS.ProcessEnv;
  target?: string;
}

const coreOnly: Channels = { core: true, codegraph: false, entire: false };

/** Ask only about optional channels; core is deliberately always selected. */
export async function promptChannels(_target?: string): Promise<Channels> {
  const selected = await checkbox<OptionalChannel>({
    message: "Select optional pi-squad channels",
    choices: [
      { name: "codegraph", value: "codegraph" },
      { name: "entire", value: "entire" },
    ],
  });

  return {
    core: true,
    codegraph: selected.includes("codegraph"),
    entire: selected.includes("entire"),
  };
}

function values(input: string | string[] | undefined): string[] {
  if (input === undefined) return [];
  const parts = Array.isArray(input) ? input : input.split(",");
  return parts.map((part) => part.trim().toLowerCase()).filter(Boolean);
}

function optionalChannels(input: string | string[] | undefined): Set<OptionalChannel> {
  const result = new Set<OptionalChannel>();
  for (const value of values(input)) {
    if (value === "codegraph" || value === "entire") result.add(value);
    else if (value !== "core") throw new Error(`Unknown channel: ${value}`);
  }
  return result;
}

function withChannels(channels: Set<OptionalChannel>): Channels {
  return {
    core: true,
    codegraph: channels.has("codegraph"),
    entire: channels.has("entire"),
  };
}

/**
 * Decide channels in the documented non-interactive precedence order.
 * Explicit flags win over environment variables; no tty always falls back to core.
 */
export async function decideChannels(opts: ChannelDecisionOptions = {}): Promise<Channels> {
  if (opts.all) return { core: true, codegraph: true, entire: true };

  const explicitWith = values(opts.with);
  const explicitWithout = values(opts.without);
  if (explicitWith.length > 0 && explicitWithout.length > 0) {
    throw new Error("Cannot combine --with and --without");
  }

  if (explicitWith.length > 0) {
    return withChannels(optionalChannels(explicitWith));
  }

  if (explicitWithout.length > 0) {
    const exclude = optionalChannels(explicitWithout);
    return {
      core: true,
      codegraph: !exclude.has("codegraph"),
      entire: !exclude.has("entire"),
    };
  }

  if (opts.yes) return { ...coreOnly };

  const env = opts.env ?? process.env;
  const environmentWith = values(env.PISQUAD_WITH);
  const environmentWithout = values(env.PISQUAD_WITHOUT);
  if (environmentWith.length > 0 && environmentWithout.length > 0) {
    throw new Error("Cannot combine PISQUAD_WITH and PISQUAD_WITHOUT");
  }

  if (environmentWith.length > 0) {
    return withChannels(optionalChannels(environmentWith));
  }

  if (environmentWithout.length > 0) {
    const exclude = optionalChannels(environmentWithout);
    return {
      core: true,
      codegraph: !exclude.has("codegraph"),
      entire: !exclude.has("entire"),
    };
  }

  if (isInteractive()) return promptChannels(opts.target);
  return { ...coreOnly };
}

import { readCliVersion, resolveAssetsVersion } from "../lib/version.js";

/**
 * Print CLI and assets versions.
 * Format: `pisquad <cliVersion> (assets <version>)`
 */
export function versionCommand(): void {
  const cliVersion = readCliVersion();
  const assetsVersion = resolveAssetsVersion(cliVersion);
  console.log(`pisquad ${cliVersion} (assets ${assetsVersion})`);
}

