// src/lib/diff.ts

import { createHash } from "node:crypto";
import { createReadStream, lstatSync, readdirSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { resolvePackageRoot } from "./paths.js";

export interface FileHashMap {
  [relPath: string]: string;
}

export interface Sha256DirOptions {
  /** Skip a relative path (POSIX-style, slash-separated). Return true to ignore. */
  ignore?: (relPath: string) => boolean;
}

export interface PkgInclude {
  /** Subtree inside the pisquad package, e.g. ".pi" or "docs". */
  pkgSubPath: string;
  /** Matching subtree inside the install target, e.g. ".pi" or "docs". */
  targetSubPath: string;
}

export interface DiffTreeOptions {
  /** Skip a relative path (POSIX-style, slash-separated). Applied to BOTH sides. */
  ignore?: (relPath: string) => boolean;
}

export interface DiffPlan {
  modified: Array<{ relPath: string; fromHash: string; toHash: string }>;
  added: Array<{ relPath: string; toHash: string }>;
  removed: Array<{ relPath: string; fromHash: string }>;
  unchanged: Array<{ relPath: string }>;
}

/**
 * Runtime artifacts that are not "user modifications" — regenerated by tools,
 * managed by pisquad itself, or OS debris. Diff ignores these on both sides.
 */
export const DEFAULT_IGNORE_NAMES = new Set([
  "node_modules",
  ".pisquad",
  ".codegraph",
  ".entire",
  ".DS_Store",
]);

export function defaultIgnore(relPath: string): boolean {
  return relPath.split("/").some((seg) => DEFAULT_IGNORE_NAMES.has(seg));
}

/** Hash a single file with sha256. Returns lowercase hex digest. */
export async function sha256File(path: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const hash = createHash("sha256");
    const stream = createReadStream(path);
    stream.on("error", reject);
    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("end", () => resolve(hash.digest("hex")));
  });
}

/** Recursively hash every regular file under `path`. Returns `{ relPath: sha256 }`. */
export async function sha256Dir(path: string, opts: Sha256DirOptions = {}): Promise<FileHashMap> {
  const result: FileHashMap = {};
  const walk = async (dir: string): Promise<void> => {
    let entries: ReturnType<typeof readdirSync>;
    try {
      entries = readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      const stat = lstatSync(full);
      if (stat.isSymbolicLink()) continue;
      const rel = relative(path, full).split(sep).join("/");
      if (opts.ignore?.(rel)) continue;
      if (stat.isDirectory()) {
        await walk(full);
      } else if (stat.isFile()) {
        result[rel] = await sha256File(full);
      }
    }
  };
  await walk(path);
  return result;
}

export interface ResolvedInclude {
  pkgSubPathAbs: string;
  targetSubPathAbs: string;
}

/**
 * Compare the package's payload subtrees against the matching subtrees in the
 * install target.
 *
 * Each `pkgIncludes` entry pairs one subtree inside the pisquad package
 * (e.g. `.pi`) with the matching subtree inside the install target
 * (e.g. `.pi`). The caller MUST explicitly include the `docs` subtree
 * (`{ pkgSubPath: "docs", targetSubPath: "docs" }`) — see PRD §6 "upgrade
 * 安全机制": docs is the most frequently consumer-edited area and must be
 * diffed alongside `.pi` so the upgrader can back up user changes.
 *
 * Resulting `modified` and `removed` entries use relPath relative to the
 * install target, so they can be passed directly to `backup.createBackup`.
 */
export async function diffTree(
  target: string,
  pkgIncludes: PkgInclude[],
  opts: DiffTreeOptions = {},
): Promise<DiffPlan> {
  const ignore = opts.ignore ?? defaultIgnore;
  const pkgRoot = resolvePackageRoot();

  // Build fromHash (target) and toHash (pkg) maps keyed by relPath-from-target.
  const fromHash: FileHashMap = {};
  const toHash: FileHashMap = {};

  for (const inc of pkgIncludes) {
    const pkgAbs = join(pkgRoot, inc.pkgSubPath);
    const targetAbs = join(target, inc.targetSubPath);
    const pkgMap = await sha256Dir(pkgAbs, { ignore });
    const targetMap = await sha256Dir(targetAbs, { ignore });
    // Re-key: pkg map uses paths relative to pkgAbs; target map uses paths
    // relative to targetAbs. We want relPath relative to target, so re-map.
    for (const [rel, hash] of Object.entries(pkgMap)) {
      toHash[rel] = hash;
    }
    for (const [rel, hash] of Object.entries(targetMap)) {
      fromHash[rel] = hash;
    }
  }

  const plan: DiffPlan = { modified: [], added: [], removed: [], unchanged: [] };
  const seen = new Set<string>();
  for (const rel of Object.keys(toHash)) {
    seen.add(rel);
    if (!(rel in fromHash)) {
      plan.added.push({ relPath: rel, toHash: toHash[rel] });
    } else if (fromHash[rel] !== toHash[rel]) {
      plan.modified.push({ relPath: rel, fromHash: fromHash[rel], toHash: toHash[rel] });
    } else {
      plan.unchanged.push({ relPath: rel });
    }
  }
  for (const rel of Object.keys(fromHash)) {
    if (seen.has(rel)) continue;
    plan.removed.push({ relPath: rel, fromHash: fromHash[rel] });
  }

  // Stable sort for deterministic output.
  const byRel = (a: { relPath: string }, b: { relPath: string }) => a.relPath.localeCompare(b.relPath);
  plan.modified.sort(byRel);
  plan.added.sort(byRel);
  plan.removed.sort(byRel);
  plan.unchanged.sort(byRel);

  return plan;
}
```

