```typescript
// src/lib/backup.ts

import { existsSync, lstatSync, readdirSync, statSync, unlinkSync } from "node:fs";
import { join, relative } from "node:path";
import { ensureDir } from "./fs-safe.js";
import { execCapture } from "./env.js";

export interface BackupEntry {
  /** Path relative to the install target, e.g. "docs/README.md" or ".pi/extensions/entire/index.ts". */
  relPath: string;
}

export interface BackupResult {
  path: string;
  fileCount: number;
  bytes: number;
}

export interface BackupInfo {
  path: string;
  fileName: string;
  iso: string;       // parsed from file name
  label: string;
  bytes: number;
  modifiedAt: Date;
}

/** Path to the backups directory inside an install target. */
export function backupDir(target: string): string {
  return join(target, ".pi", ".pisquad", "backups");
}

/** Build the iso timestamp suffix used in backup file names. */
function isoStamp(date: Date = new Date()): string {
  // ISO 8601 with milliseconds stripped and Z preserved.
  // e.g. "2026-01-15T10:30:45.123Z" -> "2026-01-15T103045Z"
  return date.toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
}

const FILE_NAME_RE = /^(\d{8}T\d{6}Z)-(.+)\.tar\.gz$/;

/**
 * Tar up the listed files and write them to
 * `<target>/.pi/.pisquad/backups/<iso>-<label>.tar.gz`. Paths inside the
 * archive are relative to `target` (e.g. `docs/README.md`).
 *
 * The system `tar` CLI is required — backup failure aborts the upgrade.
 * Refusing to silently swallow a missing tar makes the safety net real.
 */
export async function createBackup(target: string, files: BackupEntry[], label: string): Promise<BackupResult> {
  if (files.length === 0) {
    throw new Error("createBackup: no files to back up");
  }
  if (!/^[a-z0-9-]+$/i.test(label)) {
    throw new Error(`createBackup: invalid label "${label}" (only [a-z0-9-] allowed)`);
  }

  const dir = backupDir(target);
  ensureDir(dir);

  const stamp = isoStamp();
  const fileName = `${stamp}-${label}.tar.gz`;
  const out = join(dir, fileName);

  // Validate every file exists and is a regular file. Backup must not silently
  // include ghost entries — that would let an upgrader overwrite a file that
  // was never backed up.
  for (const f of files) {
    const abs = join(target, f.relPath);
    if (!existsSync(abs)) {
      throw new Error(`createBackup: file does not exist: ${f.relPath}`);
    }
    const stat = lstatSync(abs);
    if (!stat.isFile()) {
      throw new Error(`createBackup: not a regular file: ${f.relPath}`);
    }
  }

  const relativePaths = files.map((f) => f.relPath);
  const result = await execCapture("tar", [
    "-czf", out,
    "-C", target,
    ...relativePaths,
  ]);

  if (result.exitCode !== 0) {
    throw new Error(`createBackup: tar exited ${result.exitCode}\nstderr: ${result.stderr.trim()}`);
  }

  const stat = statSync(out);
  console.log(`Backed up ${files.length} files → ${out}`);
  return { path: out, fileCount: files.length, bytes: stat.size };
}

/** List existing backups in time-ascending order. */
export function listBackups(target: string): BackupInfo[] {
  const dir = backupDir(target);
  if (!existsSync(dir)) return [];
  const entries = readdirSync(dir)
    .map((name) => {
      const match = FILE_NAME_RE.exec(name);
      if (!match) return null;
      const [, iso, label] = match;
      const path = join(dir, name);
      const stat = statSync(path);
      return { path, fileName: name, iso, label, bytes: stat.size, modifiedAt: stat.mtime };
    })
    .filter((info): info is BackupInfo => info !== null);
  entries.sort((a, b) => a.iso.localeCompare(b.iso));
  return entries;
}

/**
 * Delete backups whose iso timestamp is strictly before `before`. Returns the
 * number of files pruned. Not auto-invoked by upgrade; reserved for the
 * future `pisquad restore` workflow.
 */
export function pruneBackup(target: string, before: Date): number {
  const beforeIso = isoStamp(before);
  const backups = listBackups(target);
  let pruned = 0;
  for (const b of backups) {
    if (b.iso >= beforeIso) continue;
    try {
      unlinkSync(b.path);
      pruned++;
    } catch {
      // Best-effort: skip unremovable files.
    }
  }
  return pruned;
}
