// Verification script for src/lib/diff.ts + src/lib/backup.ts (task 09).
// Runs against a synthesized pkgRoot + target tree under /tmp.

import { mkdirSync, writeFileSync, rmSync, readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { execSync } from "node:child_process";
import {
  diffTree,
  sha256File,
  sha256Dir,
  defaultIgnore,
  DEFAULT_IGNORE_NAMES,
  type DiffPlan,
} from "../../home/sankabox/code/PiExperiment/src/lib/diff.ts";
import { createBackup, listBackups } from "../../home/sankabox/code/PiExperiment/src/lib/backup.ts";

const SCRATCH = "/tmp/pisquad-task09-verify";
const PKG_ROOT = join(SCRATCH, "pkg");
const TARGET = join(SCRATCH, "target");

function reset(): void {
  rmSync(SCRATCH, { recursive: true, force: true });
  mkdirSync(PKG_ROOT, { recursive: true });
  mkdirSync(TARGET, { recursive: true });
}

function write(rel: string, content: string, base: string): void {
  const abs = join(base, rel);
  mkdirSync(join(abs, ".."), { recursive: true });
  writeFileSync(abs, content);
}

function expect(cond: boolean, msg: string): void {
  if (!cond) {
    console.error("FAIL:", msg);
    process.exit(1);
  }
  console.log("ok:", msg);
}

async function main(): Promise<void> {
  reset();

  // 1. Build pkg tree (assets/.pi/ + assets/docs/).
  write("agents/a.md", "agent-a v1", PKG_ROOT);
  write("skills/s.md", "skill-s v1", PKG_ROOT);
  write("extensions/subagent/index.ts", "subagent v1", PKG_ROOT);
  // node_modules under pkg should be ignored too — proves defaultIgnore works
  // on the pkg side (defence in depth even though assets normally don't carry
  // a node_modules).
  write("extensions/subagent/node_modules/pkg/index.js", "should be ignored", PKG_ROOT);
  write("docs/README.md", "docs readme v1", PKG_ROOT);
  write("docs/tasks/t.md", "tasks t v1", PKG_ROOT);
  // NEW in pkg (added in this version).
  write("extensions/old/index.ts", "old ext v1", PKG_ROOT);
  write("docs/new.md", "brand new doc", PKG_ROOT);
  // Pisquad runtime dir under pkg — should be ignored.
  write(".pisquad/state.json", "should be ignored", PKG_ROOT);

  // 2. Build target tree (current install).
  write("agents/a.md", "agent-a v1", TARGET); // unchanged
  write("skills/s.md", "skill-s USER-EDITED", TARGET); // modified
  write("extensions/subagent/index.ts", "subagent v1", TARGET); // unchanged
  write("extensions/entire/index.ts", "entire installed", TARGET); // removed (pkg drops it)
  write("docs/README.md", "docs readme USER-EDITED", TARGET); // modified — docs subtree!
  write("docs/tasks/t.md", "tasks t v1", TARGET); // unchanged
  // node_modules + .codegraph + .entire + .DS_Store — should ALL be ignored.
  write("extensions/subagent/node_modules/pkg/index.js", "user-installed npm pkg", TARGET);
  write("agents/.DS_Store", "junk", TARGET);
  write(".codegraph/cache.json", "codegraph tool cache", TARGET);
  write(".entire/meta.json", "entire tool meta", TARGET);

  // 3. Sanity-check ignore predicate before running the full diff.
  expect(defaultIgnore("node_modules/x") === true, "ignore node_modules");
  expect(defaultIgnore(".pisquad/state.json") === true, "ignore .pisquad");
  expect(defaultIgnore(".codegraph/x") === true, "ignore .codegraph");
  expect(defaultIgnore(".entire/x") === true, "ignore .entire");
  expect(defaultIgnore("agents/.DS_Store") === true, "ignore .DS_Store");
  expect(defaultIgnore("agents/a.md") === false, "keep real files");

  // 4. sha256File + sha256Dir sanity.
  const hash1 = await sha256File(join(PKG_ROOT, "agents/a.md"));
  expect(/^[0-9a-f]{64}$/.test(hash1), "sha256File returns 64-hex digest");
  const pkgHashes = await sha256Dir(join(PKG_ROOT, ".pi"));
  expect("agents/a.md" in pkgHashes, "sha256Dir keys by POSIX relPath");
  expect(!("extensions/subagent/node_modules/pkg/index.js" in pkgHashes), "sha256Dir skips ignored");

  // 5. diffTree — explicitly include BOTH .pi and docs subtrees.
  const plan: DiffPlan = await diffTree(TARGET, [
    { pkgSubPath: ".pi", targetSubPath: ".pi" },
    { pkgSubPath: "docs", targetSubPath: "docs" },
  ]);

  console.log("\n--- diff plan ---");
  console.log("modified:", plan.modified.map((m) => m.relPath));
  console.log("added:   ", plan.added.map((a) => a.relPath));
  console.log("removed: ", plan.removed.map((r) => r.relPath));
  console.log("unchanged:", plan.unchanged.map((u) => u.relPath));

  // Verify each category.
  expect(
    plan.modified.map((m) => m.relPath).join(",") === "docs/README.md,skills/s.md",
    `modified is exactly docs/README.md + skills/s.md (got ${plan.modified.map((m) => m.relPath).join(",")})`,
  );
  expect(
    plan.added.map((a) => a.relPath).join(",") === "docs/new.md,extensions/old/index.ts",
    `added is exactly docs/new.md + extensions/old/index.ts (got ${plan.added.map((a) => a.relPath).join(",")})`,
  );
  expect(
    plan.removed.map((r) => r.relPath).join(",") === "extensions/entire/index.ts",
    `removed is exactly extensions/entire/index.ts (got ${plan.removed.map((r) => r.relPath).join(",")})`,
  );
  expect(
    plan.unchanged.map((u) => u.relPath).join(",") ===
      "agents/a.md,docs/tasks/t.md,extensions/subagent/index.ts",
    `unchanged contains the three matching files (got ${plan.unchanged.map((u) => u.relPath).join(",")})`,
  );

  // Critical: docs subtree IS included (PRD §6 requirement).
  expect(
    plan.modified.some((m) => m.relPath === "docs/README.md"),
    "docs subtree is included in the diff (docs/README.md modified)",
  );

  // Critical: ignored entries do NOT appear in any bucket.
  for (const m of plan.modified) expect(!defaultIgnore(m.relPath), `modified ${m.relPath} is not ignored`);
  for (const a of plan.added) expect(!defaultIgnore(a.relPath), `added ${a.relPath} is not ignored`);
  for (const r of plan.removed) expect(!defaultIgnore(r.relPath), `removed ${r.relPath} is not ignored`);
  for (const u of plan.unchanged) expect(!defaultIgnore(u.relPath), `unchanged ${u.relPath} is not ignored`);

  // Critical: the user-installed node_modules inside the target's .pi/extensions
  // does not surface as "modified" — proves defaultIgnore covers user tree too.
  expect(
    !plan.modified.some((m) => m.relPath.includes("node_modules")),
    "node_modules inside target is ignored (not classified as modified)",
  );
  expect(
    !plan.removed.some((r) => r.relPath.startsWith(".codegraph")),
    ".codegraph inside target is ignored (not classified as removed)",
  );

  // 6. createBackup — feed modified entries straight in (the documented
  // "diffTree result feeds createBackup" coupling).
  console.log("\n--- createBackup ---");
  const backup = await createBackup(TARGET, plan.modified, "before-upgrade");
  expect(existsSync(backup.path), `backup tar.gz exists at ${backup.path}`);
  expect(backup.fileCount === 2, `backup contains 2 files (got ${backup.fileCount})`);
  expect(/^\d{8}T\d{6}Z-before-upgrade\.tar\.gz$/.test(backup.path.split("/").pop() ?? ""),
    "backup file name matches <iso>-<label>.tar.gz (no `:` or `.`)");
  expect(backup.bytes > 0, `backup has non-zero size (got ${backup.bytes} bytes)`);

  // List tar contents and assert.
  const tarList = execSync(`tar tzf "${backup.path}"`, { encoding: "utf8" }).trim().split("\n").sort();
  console.log("tar entries:", tarList);
  expect(tarList.join(",") === "docs/README.md,skills/s.md", `tar contains expected entries (got ${tarList.join(",")})`);

  // listBackups round-trip.
  const listed = listBackups(TARGET);
  expect(listed.length === 1, `listBackups returns the one backup (got ${listed.length})`);
  expect(listed[0].iso.length === 16, `iso stamp format (got ${listed[0].iso})`);
  expect(listed[0].label === "before-upgrade", `label round-trips (got ${listed[0].label})`);

  // 7. createBackup rejects empty input + invalid label.
  let threwEmpty = false;
  try {
    await createBackup(TARGET, [], "noop");
  } catch {
    threwEmpty = true;
  }
  expect(threwEmpty, "createBackup rejects empty file list");

  let threwLabel = false;
  try {
    await createBackup(TARGET, [{ relPath: "agents/a.md" }], "");
  } catch {
    threwLabel = true;
  }
  expect(threwLabel, "createBackup rejects empty label");

  let threwMissing = false;
  try {
    await createBackup(TARGET, [{ relPath: "does/not/exist.md" }], "before-upgrade");
  } catch {
    threwMissing = true;
  }
  expect(threwMissing, "createBackup rejects files that don't exist on disk");

  // 8. Custom ignore filter overrides the default.
  const customPlan = await diffTree(
    TARGET,
    [{ pkgSubPath: ".pi", targetSubPath: ".pi" }],
    { ignore: (rel) => rel === "agents/a.md" },
  );
  expect(
    !customPlan.unchanged.some((u) => u.relPath === "agents/a.md") &&
      !customPlan.modified.some((m) => m.relPath === "agents/a.md") &&
      !customPlan.removed.some((r) => r.relPath === "agents/a.md"),
    "custom ignore filters agents/a.md out of the plan",
  );

  console.log("\nALL CHECKS PASSED");
  console.log("DEFAULT_IGNORE_NAMES:", [...DEFAULT_IGNORE_NAMES]);
}

main().catch((error) => {
  console.error("UNCAUGHT:", error);
  process.exit(1);
});

