const SCRATCH = "/tmp/pisquad-task09-verify";
const PKG_ROOT = join(SCRATCH, "pkg");
const TARGET = join(SCRATCH, "target");

function reset(): void {
  rmSync(SCRATCH, { recursive: true, force: true });
  mkdirSync(PKG_ROOT, { recursive: true });
  mkdirSync(TARGET, { recursive: true });
}

function write(rel: string, content: string, base: string): void {
  const abs = join(base, rel);
  mkdirSync(join(abs, ".."), { recursive: true });
  writeFileSync(abs, content);
}

function expect(cond: boolean, msg: string): void {
  if (!cond) {
    console.error("FAIL:", msg);
    process.exit(1);
  }
  console.log("ok:", msg);
}

async function main(): Promise<void> {
  reset();

  // 1. Build pkg tree (assets/.pi/ + assets/docs/).
  write("agents/a.md", "agent-a v1", PKG_ROOT);
  write("skills/s.md", "skill-s v1", PKG_ROOT);
  write("extensions/subagent/index.ts", "subagent v1", PKG_ROOT);
  // node_modules under pkg should be ignored too — proves defaultIgnore works
  // on the pkg side (defence in depth even though assets normally don't carry
  // a node_modules).
  write("extensions/subagent/node_modules/pkg/index.js", "should be ignored", PKG_ROOT);
  write("docs/README.md", "docs readme v1", PKG_ROOT);
  write("docs/tasks/t.md", "tasks t v1", PKG_ROOT);
  // NEW in pkg (added in this version).
  write("extensions/old/index.ts", "old ext v1", PKG_ROOT);
  write("docs/new.md", "brand new doc", PKG_ROOT);
  // Pisquad runtime dir under pkg — should be ignored.
  write(".pisquad/state.json", "should be ignored", PKG_ROOT);

  // 2. Build target tree (current install).
  write("agents/a.md", "agent-a v1", TARGET); // unchanged
  write("skills/s.md", "skill-s USER-EDITED", TARGET); // modified
  write("extensions/subagent/index.ts", "subagent v1", TARGET); // unchanged
  write("extensions/entire/index.ts", "entire installed", TARGET); // removed (pkg drops it)
