// Verification script for src/lib/version.ts additions (task 10).

import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import {
  compareVersions,
  requireState,
  StateMissingError,
  readCliVersion,
  readAssetsVersion,
  type InstallState,
  type VersionDiff,
} from "/home/sankabox/code/PiExperiment/src/lib/version.ts";

const SCRATCH = "/tmp/pisquad-task10-verify";

function reset(): void {
  rmSync(SCRATCH, { recursive: true, force: true });
  mkdirSync(SCRATCH, { recursive: true });
}

function expect(cond: boolean, msg: string): void {
  if (!cond) {
    console.error("FAIL:", msg);
    process.exit(1);
  }
  console.log("ok:", msg);
}

function makeState(overrides: Partial<InstallState> = {}): InstallState {
  return {
    version: "1.0.0",
    cliVersion: "0.1.0",
    channels: { core: true, codegraph: false, entire: false },
    installedAt: "2026-01-15T10:30:45.000Z",
    ...overrides,
    channels: { core: true, codegraph: false, entire: false, ...overrides.channels },
  };
}

function main(): void {
  reset();

  // 1. readCliVersion / readAssetsVersion come from package.json + assets/.
  const cli = readCliVersion();
  const assets = readAssetsVersion();
  expect(/^\d+\.\d+\.\d+/.test(cli), `readCliVersion returns semver (got ${cli})`);
  expect(/^\d+\.\d+\.\d+/.test(assets), `readAssetsVersion returns semver (got ${assets})`);
  console.log("cli version:", cli);
  console.log("assets version:", assets);

  // 2. compareVersions: pure, returns VersionDiff.
  const prev = makeState({
    version: "1.0.0",
    cliVersion: "0.1.0",
    channels: { core: true, codegraph: false, entire: true },
  });
  const nextSame = makeState({ channels: { core: true, codegraph: false, entire: true } });
  const nextBumped = makeState({
    version: "1.1.0",
    cliVersion: "0.2.0",
    channels: { core: true, codegraph: true, entire: false },
  });

  const diffSame: VersionDiff = compareVersions(prev, nextSame);
  console.log("\n--- diffSame (no upgrade) ---");
  console.log(diffSame);
  expect(diffSame.versionChanged === false, "versionChanged false when versions match");
  expect(diffSame.cliVersionChanged === false, "cliVersionChanged false when cli versions match");
  expect(diffSame.newChannels.length === 0, "newChannels empty when no new channels");
  expect(diffSame.removedChannels.length === 0, "removedChannels empty when no removed channels");

  const diffUp: VersionDiff = compareVersions(prev, nextBumped);
  console.log("\n--- diffUp (assets+cli bump; channels flipped) ---");
  console.log(diffUp);
  expect(diffUp.versionChanged === true, "versionChanged true when assets version differs");
  expect(diffUp.cliVersionChanged === true, "cliVersionChanged true when cli version differs");
  expect(
    diffUp.newChannels.join(",") === "codegraph",
    `newChannels is exactly codegraph (got ${diffUp.newChannels.join(",")})`,
  );
  expect(
    diffUp.removedChannels.join(",") === "entire",
    `removedChannels is exactly entire (got ${diffUp.removedChannels.join(",")})`,
  );

  // core is always true on both sides — must NEVER appear in channel diff.
  const prevCoreTrue = makeState({ channels: { core: true, codegraph: false, entire: false } });
  const nextCoreTrue = makeState({ channels: { core: true, codegraph: true, entire: true } });
  const diffCore = compareVersions(prevCoreTrue, nextCoreTrue);
  expect(
    !diffCore.newChannels.includes("core") && !diffCore.removedChannels.includes("core"),
    "core is excluded from channel diff (always true on both sides)",
  );

  // Only versionChanged (no cli bump, no channel changes).
  const diffOnlyAssets: VersionDiff = compareVersions(
    prev,
    makeState({ version: "2.0.0", channels: prev.channels }),
  );
  expect(diffOnlyAssets.versionChanged === true, "versionChanged true when only assets bumped");
  expect(diffOnlyAssets.cliVersionChanged === false, "cliVersionChanged false when only assets bumped");
  expect(diffOnlyAssets.newChannels.length === 0 && diffOnlyAssets.removedChannels.length === 0, "channels unchanged");

  // Only cliVersionChanged.
  const diffOnlyCli: VersionDiff = compareVersions(
    prev,
    makeState({ cliVersion: "9.9.9", channels: prev.channels }),
  );
  expect(diffOnlyCli.versionChanged === false, "versionChanged false when only cli bumped");
  expect(diffOnlyCli.cliVersionChanged === true, "cliVersionChanged true when only cli bumped");

  // 3. requireState + StateMissingError.
  console.log("\n--- requireState ---");

  // Missing state.json → throws StateMissingError with target + actionable message.
  const missingDir = join(SCRATCH, "no-state");
  mkdirSync(missingDir, { recursive: true });
  let threwMissing = false;
  try {
    requireState(missingDir);
  } catch (error) {
    threwMissing = error instanceof StateMissingError && error.target === missingDir;
    if (!(error instanceof StateMissingError)) {
      console.error("FAIL: threw non-StateMissingError:", error);
      process.exit(1);
    }
    expect(error.message.includes("not installed"), `error.message contains 'not installed' (got: ${error.message})`);
    expect(error.message.includes("pisquad install"), `error.message mentions 'pisquad install' (got: ${error.message})`);
    expect(error.name === "StateMissingError", `error.name is 'StateMissingError' (got: ${error.name})`);
    expect(error.target === missingDir, `error.target is the install dir (got: ${error.target})`);
  }
  expect(threwMissing, "requireState throws StateMissingError on missing state.json");

  // Corrupt state.json → also throws StateMissingError (readState returns undefined).
  const corruptDir = join(SCRATCH, "corrupt-state");
  mkdirSync(join(corruptDir, ".pi", ".pisquad"), { recursive: true });
  writeFileSync(join(corruptDir, ".pi", ".pisquad", "state.json"), "{not-json");
  let threwCorrupt = false;
  try {
    requireState(corruptDir);
  } catch (error) {
    threwCorrupt = error instanceof StateMissingError;
  }
  expect(threwCorrupt, "requireState throws StateMissingError on corrupt state.json");

  // Valid state.json → returns the parsed object.
  const validDir = join(SCRATCH, "valid-state");
  mkdirSync(join(validDir, ".pi", ".pisquad"), { recursive: true });
  writeFileSync(
    join(validDir, ".pi", ".pisquad", "state.json"),
    JSON.stringify({
      version: "1.0.0",
      cliVersion: "0.1.0",
      channels: { core: true, codegraph: true, entire: false },
      installedAt: "2026-01-15T10:30:45.000Z",
      lastUpgradedAt: "2026-02-01T08:00:00.000Z",
    }, null, 2),
  );
  const state = requireState(validDir);
  expect(state.version === "1.0.0", "requireState returns parsed version");
  expect(state.cliVersion === "0.1.0", "requireState returns parsed cliVersion");
  expect(state.channels.codegraph === true, "requireState returns parsed channels.codegraph");
  expect(state.channels.entire === false, "requireState returns parsed channels.entire");
  expect(state.installedAt === "2026-01-15T10:30:45.000Z", "requireState returns parsed installedAt");
  expect(state.lastUpgradedAt === "2026-02-01T08:00:00.000Z", "requireState returns parsed lastUpgradedAt");

  // readState (the non-throwing sibling) still returns undefined for the
  // missing case — must not be broken by our additions.
  const readBack = require("node:fs").existsSync(join(missingDir, ".pi", ".pisquad", "state.json"));
  expect(!readBack, "(precondition) no state.json in missingDir");
  // We don't import readState here to avoid double-asserting — the install
  // command already exercises it and we confirmed via tsc that the signature
  // is unchanged.

  console.log("\nALL CHECKS PASSED");
}

main();

