```ts
import { spawn } from "node:child_process";
import { logger as defaultLogger } from "../lib/logger.js";
import { which as defaultWhich, execCapture as defaultExecCapture, type ExecCaptureResult } from "../lib/env.js";
import type { Logger } from "../lib/plugins/types.js";

export interface SelfUpdateDeps {
  which?: (cmd: string) => string | null;
  execCapture?: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>;
}

export interface SelfUpdateOptions {
  logger?: Logger;
  noSelf?: boolean;
  /** @internal Test seam: inject mocked which/execCapture. */
  deps?: SelfUpdateDeps;
}

export interface SelfUpdateResult {
  updated: boolean;
  /** Reason for skipping or failing — surfaced for diagnostics. */
  reason?: string;
}

const NPM_TIMEOUT_MS = 2 * 60 * 1000;

async function runNpmInstallGlobal(execCapture: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>): Promise<ExecCaptureResult> {
  // execCapture has no built-in timeout; replicate the spawn+timeout pattern from plugins.
  return new Promise((resolve, reject) => {
    let stdout = "";
    let stderr = "";
    let settled = false;
    const args = ["install", "-g", "pisquad@latest", "--no-audit", "--no-fund"];
    const child = spawn("npm", args, { stdio: ["ignore", "pipe", "pipe"] });
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      child.kill("SIGTERM");
      reject(new Error(`npm install -g timed out after ${NPM_TIMEOUT_MS / 1000}s`));
    }, NPM_TIMEOUT_MS);
    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk: string) => { stdout += chunk; });
    child.stderr.on("data", (chunk: string) => { stderr += chunk; });
    child.on("error", (error) => {
      clearTimeout(timer);
      if (settled) return;
      settled = true;
      reject(error);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (settled) return;
      settled = true;
      resolve({ stdout, stderr, exitCode: code ?? 1 });
    });
  });
}

async function getGlobalPrefix(execCapture: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>): Promise<string | null> {
  // Prefer `npm prefix -g` (modern). Falls back to `npm config get prefix` for very old npm.
  const r = await execCapture("npm", ["prefix", "-g"]);
  if (r.exitCode === 0 && r.stdout.trim()) return r.stdout.trim();
  const r2 = await execCapture("npm", ["config", "get", "prefix"]);
  if (r2.exitCode === 0 && r2.stdout.trim()) return r2.stdout.trim();
  return null;
}

function pathStartsWith(child: string, parent: string): boolean {
  if (!child.startsWith(parent)) return false;
  // Ensure we're matching a directory boundary (not e.g. /foo2 vs /foo)
  const next = child.charAt(parent.length);
  return next === "/" || next === "" || parent.endsWith("/");
}

export async function selfUpdate(opts: SelfUpdateOptions = {}): Promise<SelfUpdateResult> {
  const logger = opts.logger ?? defaultLogger;
  const which = opts.deps?.which ?? defaultWhich;
  const execCapture = opts.deps?.execCapture ?? defaultExecCapture;

  if (opts.noSelf === true || process.env.PISQUAD_NO_SELF === "1") {
    return { updated: false, reason: "noSelf flag or PISQUAD_NO_SELF=1" };
  }

  const currentPath = which("pisquad");
  if (!currentPath) {
    logger.info("CLI not on PATH, skipping self-update");
    return { updated: false, reason: "pisquad not on PATH" };
  }

  const globalPrefix = await getGlobalPrefix(execCapture);
  if (!globalPrefix) {
    logger.warn("Unable to determine npm global prefix, skipping self-update");
    return { updated: false, reason: "npm prefix detection failed" };
  }

  const globalBin = globalPrefix.endsWith("/bin") ? globalPrefix : `${globalPrefix.replace(/\/+$/, "")}/bin`;
  if (!pathStartsWith(currentPath, globalBin)) {
    logger.info("CLI not from global npm, skipping self-update");
    return { updated: false, reason: "not from global npm" };
  }

  // Run npm install -g with timeout.
  logger.info("Updating pisquad via npm install -g pisquad@latest …");
  let result;
  try {
    result = await runNpmInstallGlobal(execCapture);
  } catch (error) {
    throw new Error(`self-update failed: ${error instanceof Error ? error.message : String(error)}`);
  }

  if (result.exitCode !== 0) {
    const errSnippet = (result.stderr || result.stdout || "").trim().slice(0, 500);
    throw new Error(`npm install -g pisquad@latest exited ${result.exitCode}\n${errSnippet}`);
  }

  return { updated: true };
}
