// Test harness for selfUpdate. Verifies all branches without invoking real npm.
import { selfUpdate } from "./src/upgrade/self.js";

async function main() {
  let failed = 0;

  function check(name: string, cond: boolean, detail?: string) {
    if (cond) {
      console.log(`PASS  ${name}`);
    } else {
      console.error(`FAIL  ${name}${detail ? `: ${detail}` : ""}`);
      failed++;
    }
  }

  // 1. --no-self flag → skip
  {
    const r = await selfUpdate({ noSelf: true });
    check("noSelf:true skips", r.updated === false && (r.reason ?? "").includes("--no-self"));
  }

  // 2. PISQUAD_NO_SELF=1 → skip
  {
    const orig = process.env.PISQUAD_NO_SELF;
    process.env.PISQUAD_NO_SELF = "1";
    try {
      const r = await selfUpdate();
      check("PISQUAD_NO_SELF=1 skips", r.updated === false && (r.reason ?? "").includes("PISQUAD_NO_SELF=1"));
    } finally {
      if (orig === undefined) delete process.env.PISQUAD_NO_SELF;
      else process.env.PISQUAD_NO_SELF = orig;
    }
  }

  // 3. which returns null → skip with "not on PATH"
  {
    const r = await selfUpdate({ deps: { which: () => null } });
    check("which returns null skips", r.updated === false && (r.reason ?? "").includes("PATH"));
  }

  // 4. npm prefix detection fails → skip (no exception)
  {
    const r = await selfUpdate({
      deps: {
        which: () => "/usr/local/bin/pisquad",
        execCapture: async () => ({ stdout: "", stderr: "boom", exitCode: 1 }),
      },
    });
    check("npm prefix detection failure skips", r.updated === false && (r.reason ?? "").includes("prefix"));
  }

  // 5. Non-global binary path → skip with "not from global npm"
  {
    const r = await selfUpdate({
      deps: {
        which: () => "/home/dev/pisquad-cli/dist/bin.js",
        execCapture: async (cmd, args) => {
          if (cmd === "npm" && args?.[0] === "prefix" && args[1] === "-g") {
            return { stdout: "/usr/local\n", stderr: "", exitCode: 0 };
          }
          throw new Error("unexpected call");
        },
      },
    });
    check("non-global path skips", r.updated === false && (r.reason ?? "").includes("global"));
  }

  // 6. Global binary, npm install succeeds → updated:true
  {
    const r = await selfUpdate({
      deps: {
        which: () => "/usr/local/bin/pisquad",
        execCapture: async (cmd, args) => {
          if (cmd === "npm" && args?.[0] === "prefix" && args[1] === "-g") {
            return { stdout: "/usr/local\n", stderr: "", exitCode: 0 };
          }
          throw new Error("unexpected exec call");
        },
        runNpmInstallGlobal: async () => ({ stdout: "+ pisquad@1.0.0\n", stderr: "", exitCode: 0 }),
      },
    });
    check("global path + successful install → updated:true", r.updated === true);
  }

  // 7. Global binary, npm install fails → throws
  {
    let caught: Error | null = null;
    try {
      await selfUpdate({
        deps: {
          which: () => "/usr/local/bin/pisquad",
          execCapture: async (cmd, args) => {
            if (cmd === "npm" && args?.[0] === "prefix" && args[1] === "-g") {
              return { stdout: "/usr/local\n", stderr: "", exitCode: 0 };
            }
            throw new Error("unexpected");
          },
          runNpmInstallGlobal: async () => ({ stdout: "", stderr: "ENOENT no such package", exitCode: 1 }),
        },
      });
    } catch (e) {
      caught = e as Error;
    }
    check(
      "global path + failing install throws",
      caught !== null && caught.message.includes("exited 1") && caught.message.includes("ENOENT"),
      caught?.message,
    );
  }

  // 8. npm prefix has trailing slash + falls back to legacy `npm config get prefix`
  {
    let usedLegacy = false;
    const r = await selfUpdate({
      deps: {
        which: () => "/home/user/.nvm/versions/node/v22.23.1/bin/pisquad",
        execCapture: async (cmd, args) => {
          if (cmd === "npm" && args?.[0] === "prefix" && args[1] === "-g") {
            return { stdout: "", stderr: "", exitCode: 1 };
          }
          if (cmd === "npm" && args?.[0] === "config" && args[1] === "get") {
            usedLegacy = true;
            return { stdout: "/home/user/.nvm/versions/node/v22.23.1/\n", stderr: "", exitCode: 0 };
          }
          throw new Error("unexpected");
        },
        runNpmInstallGlobal: async () => ({ stdout: "", stderr: "", exitCode: 0 }),
      },
    });
    check(
      "trailing-slash prefix + legacy fallback → updated:true",
      r.updated === true && usedLegacy === true,
    );
  }

  if (failed > 0) {
    console.error(`\n${failed} test(s) failed`);
    process.exit(1);
  } else {
    console.log("\nAll selfUpdate tests passed.");
  }
}

main().catch((err) => {
  console.error("Unhandled error:", err);
  process.exit(1);
});

