/**
 * Test seam for `selfUpdate`'s three-branch version comparison.
 * Run with: npx tsx /tmp/self-update-test.ts
 *
 * Uses the `deps` hook on `selfUpdate` to mock `which`, `execCapture`, and
 * `runNpmInstallGlobal`. Captures logger output to a buffer so we can assert
 * the messages without polluting the host stdout.
 */
import { selfUpdate } from "/home/sankabox/code/PiExperiment/src/upgrade/self.js";
import { readCliVersion } from "/home/sankabox/code/PiExperiment/src/lib/version.js";
import type { ExecCaptureResult } from "/home/sankabox/code/PiExperiment/src/lib/env.js";

const captured: string[] = [];
const fakeLogger = {
  info: (m: string) => captured.push(`info: ${m}`),
  warn: (m: string) => captured.push(`warn: ${m}`),
  error: (m: string) => captured.push(`error: ${m}`),
  success: (m: string) => captured.push(`success: ${m}`),
  step: (m: string) => captured.push(`step: ${m}`),
};

function makeExecCapture(latestVersionOutput: string | { fail: true }): (cmd: string, args?: string[]) => Promise<ExecCaptureResult> {
  const FAKE_PREFIX = "/usr/local";
  return async (cmd, args = []) => {
    if (cmd === "npm" && args[0] === "prefix" && args[1] === "-g") {
      return { stdout: FAKE_PREFIX, stderr: "", exitCode: 0 };
    }
    if (cmd === "npm" && args[0] === "config" && args[1] === "get" && args[2] === "prefix") {
      return { stdout: FAKE_PREFIX, stderr: "", exitCode: 0 };
    }
    if (cmd === "npm" && args[0] === "view" && args[1] === "@nicklin/pisquad") {
      if (typeof latestVersionOutput === "string") {
        return { stdout: `${latestVersionOutput}\n`, stderr: "", exitCode: 0 };
      }
      return { stdout: "", stderr: "ENETUNREACH", exitCode: 1 };
    }
    return { stdout: "", stderr: `unmocked execCapture(${cmd} ${args.join(" ")})`, exitCode: 1 };
  };
}

const FAKE_GLOBAL_BIN = "/usr/local/bin/pisquad";
const fakeWhich = (cmd: string) => (cmd === "pisquad" ? FAKE_GLOBAL_BIN : null);

function makeInstallStub(calls: { count: number }) {
  return async () => {
    calls.count += 1;
    return { stdout: "added 1 package", stderr: "", exitCode: 0 };
  };
}

function fmt(result: { updated: boolean; reason?: string }): string {
  return `{updated: ${result.updated}, reason: "${result.reason ?? ""}"}`;
}

async function main() {
  const currentVersion = readCliVersion();
  console.log(`current CLI version: ${currentVersion}`);

  // --- Branch 1: already latest --------------------------------------------
  captured.length = 0;
  const branch1Calls = { count: 0 };
  const r1 = await selfUpdate({
    logger: fakeLogger,
    deps: {
      which: fakeWhich,
      execCapture: makeExecCapture(currentVersion),
      runNpmInstallGlobal: makeInstallStub(branch1Calls),
    },
  });
  console.log("\n[branch 1] latest === current");
  console.log("  result:", fmt(r1));
  console.log("  installStub calls:", branch1Calls.count);
  console.log("  logger lines:");
  for (const line of captured) console.log(`    ${line}`);
  const branch1Pass = r1.updated === false && r1.reason === "already latest" && branch1Calls.count === 0 && captured.some((l) => l.startsWith("info: pisquad is already up to date"));
  console.log(`  PASS=${branch1Pass}`);

  // --- Branch 2: newer version available -----------------------------------
  captured.length = 0;
  const branch2Calls = { count: 0 };
  const r2 = await selfUpdate({
    logger: fakeLogger,
    deps: {
      which: fakeWhich,
      execCapture: makeExecCapture("99.0.0"),
      runNpmInstallGlobal: makeInstallStub(branch2Calls),
    },
  });
  console.log("\n[branch 2] latest > current");
  console.log("  result:", fmt(r2));
  console.log("  installStub calls:", branch2Calls.count);
  console.log("  logger lines:");
  for (const line of captured) console.log(`    ${line}`);
  const branch2Pass = r2.updated === true && r2.reason === undefined && branch2Calls.count === 1 && captured.some((l) => l.startsWith("info: Updating pisquad v"));
  console.log(`  PASS=${branch2Pass}`);

  // --- Branch 3: npm view failed -------------------------------------------
  captured.length = 0;
  const branch3Calls = { count: 0 };
  const r3 = await selfUpdate({
    logger: fakeLogger,
    deps: {
      which: fakeWhich,
      execCapture: makeExecCapture({ fail: true }),
      runNpmInstallGlobal: makeInstallStub(branch3Calls),
    },
  });
  console.log("\n[branch 3] npm view failed");
  console.log("  result:", fmt(r3));
  console.log("  installStub calls:", branch3Calls.count);
  console.log("  logger lines:");
  for (const line of captured) console.log(`    ${line}`);
  const branch3Pass = r3.updated === false && r3.reason === "npm view failed" && branch3Calls.count === 0 && captured.some((l) => l.startsWith("warn: Could not check latest pisquad version"));
  console.log(`  PASS=${branch3Pass}`);

  console.log(`\nALL PASS=${branch1Pass && branch2Pass && branch3Pass}`);
  process.exit(branch1Pass && branch2Pass && branch3Pass ? 0 : 1);
}

main().catch((e) => {
  console.error("UNCAUGHT:", e);
  process.exit(2);
});

